#!/usr/bin/env node
import { execFileSync } from "node:child_process";

const blockedPrefixes = [
  "node_modules/",
  "dist/",
  "target/",
  "src-tauri/target/",
  "src-tauri/gen/",
  "src-tauri/permissions/autogenerated/",
  "test-results/",
  "playwright-report/",
  "diagnostics/",
];

const blockedNames = new Set([
  "komorebi.sqlite",
  "komorebi.sqlite-shm",
  "komorebi.sqlite-wal",
  "msedgedriver.exe",
]);

function gitLines(args) {
  const output = execFileSync("git", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });

  return output
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
}

function normalizePath(path) {
  return path.replace(/\\/g, "/").replace(/^"|"$/g, "");
}

const tracked = gitLines(["ls-files"]).map(normalizePath);
const staged = gitLines(["diff", "--cached", "--name-only"]).map(normalizePath);
const offenders = new Set();

for (const path of [...tracked, ...staged]) {
  const normalized = normalizePath(path);
  const fileName = normalized.split("/").at(-1) ?? normalized;
  if (
    blockedPrefixes.some((prefix) => normalized.startsWith(prefix)) ||
    blockedNames.has(fileName)
  ) {
    offenders.add(normalized);
  }
}

if (offenders.size > 0) {
  console.error("Generated/runtime artifacts must not be tracked or staged:");
  for (const offender of [...offenders].sort()) {
    console.error(`- ${offender}`);
  }
  process.exit(1);
}

console.log("No generated/runtime artifacts are tracked or staged.");
